<template><footer v-if="lastPage > 1" class="flex flex-col gap-3 border-t border-slate-100 px-4 py-4 text-sm sm:flex-row sm:items-center sm:justify-between"><span class="text-slate-600">{{ summary }}</span><div class="flex items-center gap-2"><button type="button" class="pager" :disabled="page <= 1 || loading" @click="$emit('change', page - 1)"><i class="pi pi-angle-left" aria-hidden="true"></i>Anterior</button><span class="whitespace-nowrap text-slate-600">Página {{ page }} de {{ lastPage }}</span><button type="button" class="pager" :disabled="page >= lastPage || loading" @click="$emit('change', page + 1)">Siguiente<i class="pi pi-angle-right" aria-hidden="true"></i></button></div></footer></template>
<script setup>defineProps({ page: { type: Number, required: true }, lastPage: { type: Number, required: true }, summary: { type: String, required: true }, loading: Boolean }); defineEmits(['change']);</script>
<style scoped>.pager { display:inline-flex; align-items:center; gap:.35rem; border:1px solid rgb(203 213 225); border-radius:.55rem; padding:.45rem .65rem; font-weight:700; color:rgb(51 65 85); }.pager:disabled{cursor:not-allowed;opacity:.45}.pager:focus-visible{outline:2px solid rgb(37 99 235);outline-offset:2px}</style>
